 function click(event){const b=event.target.closest('[data-life-tab],[data-life-store],[data-life-light],[data-life-place],[data-life-craft],[data-life-serve],[data-life-pack],[data-life-unpack],[data-life-buy],[data-life-plant],[data-life-harvest],[data-life-photo],[data-life-festival]');if(!b||b.disabled)return;
