</script><script>/* Connection settings are an explicit local preference, separate from MVU. */
(()=>{
 const $=id=>document.getElementById(id),empty=()=>({version:1,mode:null,activeProfileId:'',profiles:[]});
 let bridge=null,openPage=null,config=empty(),editing='',busy=false,disposed=false,lookup=0;
 const form=()=>$('ema-api-form');
 function message(text,error=false){$('ema-settings-feedback').textContent=text;$('ema-settings-feedback').dataset.error=String(error);}
 function label(){if(config.mode==='main')return '跟随主 API 预设';if(config.mode==='independent'){const p=config.profiles.find(x=>x.id===config.activeProfileId);return p?'独立 API · '+p.name+' · '+p.model:'尚未配置';}return '尚未配置';}
 function status(){const text=label();$('ema-settings-current').textContent=text;$('ema-api-status').textContent=config.mode?'心愿来信通道：'+text:'尚未配置请求 API · 请先打开请求设置。';}
