 function fields(profile){editing=profile?.id||'';$('ema-profile-select').value=editing;for(const [id,key] of [['ema-profile-name','name'],['ema-api-url','url'],['ema-api-key','key'],['ema-api-model','model']])$(id).value=profile?.[key]||'';$('ema-api-key').type='password';$('ema-key-visibility').textContent='显示';$('ema-key-visibility').setAttribute('aria-pressed','false');$('ema-delete-profile').disabled=!editing;$('ema-model-list').replaceChildren(new Option('选择模型',''));$('ema-model-list').hidden=true;}
 function render(){status();const select=$('ema-profile-select');select.replaceChildren(new Option('新建方案',''));for(const p of config.profiles)select.add(new Option(p.name,p.id));form().querySelectorAll('[name=ema-api-mode]').forEach(el=>el.checked=el.value===config.mode);fields(config.profiles.find(p=>p.id===(editing||config.activeProfileId)));modeView();}
