 async function open(){lookup++;locked(false);$('ema-fetch-models').textContent='拉取模型';editing='';const loaded=await load();if(disposed)return;render();if(loaded)message(config.mode?'编辑后请保存；切换方案会载入已保存内容。':'请选择模式并保存，设置前不会发起心愿请求。');$('ema-api-preview-note').hidden=!bridge?.emaPreview;}
