   const id=editing||'ema-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);
   const profile={id,name:$('ema-profile-name').value,url:$('ema-api-url').value,key:$('ema-api-key').value,model:$('ema-api-model').value};
