  try{const list=await Promise.race([bridge.listEmaModels({url:$('ema-api-url').value,key:$('ema-api-key').value}),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('拉取模型超时，可检查连接或手动填写模型名。')),20000);})]);if(disposed||stamp!==lookup)return;const select=$('ema-model-list');select.replaceChildren(new Option('选择模型',''));for(const id of list)select.add(new Option(id,id));select.hidden=!list.length;message(list.length?'已拉取 '+list.length+' 个模型，请选择后保存。':'接口没有返回可选模型，可以手动填写模型名。');}
