  async function invokeAction(type, payload, success, control) {
    if (!bridge || typeof bridge.act !== 'function') {
      if (control) control.disabled = false;
      return showToast('界面桥接尚未连接。');
    }
    const robeAction=['setOutfit','nameOutfit'].includes(type);
    if(robeAction)window.MikageWardrobeDesk?.operation('pending',type==='setOutfit'?'正在更换衣装…':'正在保存纪念名…');
    const emaAction=['acceptEma','dismissEma','pauseEma','resumeEma','refresh'].includes(type);
    const emaKey=type==='refresh'?'$refresh':String(payload?.id||'');
    if(emaAction&&emaPending.has(emaKey))return false;
    let emaSucceeded=false,emaFailure='';
    if(emaAction){emaPending.set(emaKey,type);window.MikageEmaDesk?.operation('pending',emaKey,type);}
    try {
      if (control) control.disabled = true;
      if(type==='refresh'){$('#ema-cancel-request').hidden=false;control?.querySelector('span')?.replaceChildren(document.createTextNode('心愿正在赶来…'));}
      let result;
      if (type === 'refresh') result = await bridge.act('refreshBoard', {});
      else if (type === 'acceptEma') result = await bridge.act('acceptEma', payload);
      else if (type === 'dismissEma') result = await bridge.act('dismissEma', payload);
      else if (type === 'pauseEma') result = await bridge.act('pauseEma', payload);
      else if (type === 'resumeEma') result = await bridge.act('resumeEma', payload);
      else if (type === 'travel') result = await bridge.act('travel', payload);
      else if (type === 'setOutfit') result = await bridge.act('setOutfit', payload);
      else if (type === 'addWardrobeQuest') result = await bridge.act('addWardrobeQuest', payload);
      else if (type === 'nameOutfit') result = await bridge.act('nameOutfit', payload);
      if (result && (result.ok === false || result.accepted === false)) throw new Error(result.error || '该操作未能提交。');
      let next = result && (result.snapshot || result.state);
      if (!next && typeof bridge.getState === 'function') next = await bridge.getState();
      if (next) { snapshot = unwrap(next); render(); }
      if (type === 'setOutfit' && outfitApplyPending && outfitFor(outfitApplyPending.actor) === outfitApplyPending.outfit) outfitApplyPending = null;
      showToast(success);
      emaSucceeded=true;
      if(robeAction)window.MikageWardrobeDesk?.operation('success',success);
      return true;
    } catch (error) {
      emaFailure=error?.message||'操作未提交，请重试。';
      if(robeAction)window.MikageWardrobeDesk?.operation('error',emaFailure);
      if (type === 'setOutfit') outfitApplyPending = null;
      if (control) control.disabled = false;
